// Step 1: Handle Disable
if (ig_input.enable == 0) {
    ig_output.mode = IG_ACCEPT;
    ig_output.consecutive_reject = 0;
    ig_output.nis = 0.0;
    ig_output.whitened_norm = 0.0;
    ig_output.use_measurement = 1;
    return;
}

// Step 2: Input Validation
int valid_inputs = 1;

// Check pointers
if (ig_input.residual == NULL || ig_input.variance == NULL) {
    valid_inputs = 0;
}
// Check finite
else if (!adcs_is_finite_vec3(ig_input.residual) || !adcs_is_finite_vec3(ig_input.variance)) {
    valid_inputs = 0;
}
// Check variance strictly positive
else if (ig_input.variance->x <= 0.0 || ig_input.variance->y <= 0.0 || ig_input.variance->z <= 0.0) {
    valid_inputs = 0;
}
// Check thresholds order
else if (ig_config.accept_threshold >= ig_config.reject_threshold) {
    valid_inputs = 0;
}
// Check max rejects range
else if (ig_config.max_consecutive_reject < 1 || ig_config.max_consecutive_reject > 20) {
    valid_inputs = 0;
}

if (valid_inputs == 0) {
    ig_state.mode = IG_FAULT;
    ig_output.mode = IG_FAULT;
    ig_output.consecutive_reject = ig_state.consecutive_reject; // Latch FAULT, retain count? 
    // Demand: "Invalid input latches FAULT". 
    // "Any FAULT cycle that does not evaluate a measurement publishes nis and whitened_norm as INFINITY"
    ig_output.nis = INFINITY;
    ig_output.whitened_norm = INFINITY;
    ig_output.use_measurement = 0;
    return;
}

// Step 3: Whitening
adcs_vec3_t whitened;
whitened.x = ig_input.residual->x / sqrt(ig_input.variance->x);
whitened.y = ig_input.residual->y / sqrt(ig_input.variance->y);
whitened.z = ig_input.residual->z / sqrt(ig_input.variance->z);

// Step 4: NIS Calculation
double nis = adcs_vec3_dot(&whitened, &whitened);
double whitened_norm = sqrt(nis);

// Step 5: Decision Logic
ig_mode_t current_mode = ig_state.mode;
unint32 current_count = ig_state.consecutive_reject;

if (nis <= ig_config.accept_threshold) {
    current_mode = IG_ACCEPT;
    current_count = 0;
} else if (nis < ig_config.reject_threshold) {
    if (current_mode == IG_REJECT) {
        current_count++;
    }
    // If current_mode is IG_ACCEPT, it remains IG_ACCEPT, count remains 0 (implicitly preserved as 0 from previous step or initial)
    // Note: If we were in REJECT and dropped to acceptable, we would have hit the first branch (Accept) or this branch?
    // If NIS <= accept, we go to Accept branch.
    // If accept < NIS < reject, we stay in current.
    // So if we were REJECT, and NIS drops below reject threshold but above accept, we stay REJECT and increment.
    // If NIS drops below accept, we go to Accept branch.
} else {
    // NIS >= reject_threshold
    current_mode = IG_REJECT;
    current_count++;
}

// Step 6: Fault Check
if (current_mode == IG_REJECT && current_count >= ig_config.max_consecutive_reject) {
    current_mode = IG_FAULT;
    // retain count
}

// Update State
ig_state.mode = current_mode;
ig_state.consecutive_reject = current_count;

// Step 7: Output Assignment
ig_output.mode = current_mode;
ig_output.consecutive_reject = current_count;
ig_output.nis = nis;
ig_output.whitened_norm = whitened_norm;

if (current_mode == IG_ACCEPT) {
    ig_output.use_measurement = 1;
} else {
    ig_output.use_measurement = 0;
}

