        next_mode = IG_REJECT;
        next_count = current_count + 1;
    } else {
        next_mode = current_mode;
        next_count = current_count;
    }
}

/* Check for Fault transition */
if (next_count >= ig_config.max_consecutive_reject) {
    next_mode = IG_FAULT;
    /* Retain count as per requirement */
