ig_output.consecutive_reject = 0;
ig_output.nis = 0.0;
ig_output.whitened_norm = 0.0;
ig_output.use_measurement = 1;

if (ig_input.enable == 0) {
    ig_output.mode = IG_ACCEPT;
    ig_output.consecutive_reject = 0;
    ig_output.nis = 0.0;
    ig_output.whitened_norm = 0.0;
    ig_output.use_measurement = 1;
    return;
}

int valid_inputs = 1;
if (ig_input.residual == NULL || ig_input.variance == NULL) {
    valid_inputs = 0;
} else if (!adcs_is_finite_vec3(ig_input.residual)) {
    valid_inputs = 0;
} else {
    for (int i = 0; i < 3; ++i) {
        if (!isfinite(ig_input.variance->m[i][i]) || ig_input.variance->m[i][i] <= 0.0) {
            valid_inputs = 0;
            break;
        }
    }
}

int valid_config = 1;
if (ig_config.accept_threshold < 0.0 || 
    ig_config.reject_threshold <= ig_config.accept_threshold ||
    ig_config.max_consecutive_reject < 1 || 
    ig_config.max_consecutive_reject > 20) {
    valid_config = 0;
}

if (!valid_inputs || !valid_config) {
    ig_output.mode = IG_FAULT;
    ig_output.consecutive_reject = ig_state.consecutive_reject;
    ig_output.nis = INFINITY;
    ig_output.whitened_norm = INFINITY;
    ig_output.use_measurement = 0;
    ig_state.mode = IG_FAULT;
    return;
}

adcs_vec3_t whitened = {0.0, 0.0, 0.0};
for (int i = 0; i < 3; ++i) {
    whitened.m[i] = ig_input.residual->m[i] / sqrt(ig_input.variance->m[i][i]);
}

double nis = adcs_vec3_dot(&whitened, &whitened);
double whitened_norm = sqrt(nis);

ig_output.nis = nis;
ig_output.whitened_norm = whitened_norm;

if (nis <= ig_config.accept_threshold) {
    ig_output.mode = IG_ACCEPT;
    ig_output.consecutive_reject = 0;
    ig_state.mode = IG_ACCEPT;
    ig_state.consecutive_reject = 0;
} else if (nis < ig_config.reject_threshold) {
    ig_output.mode = ig_state.mode;
    ig_output.consecutive_reject = ig_state.consecutive_reject;

    if (ig_state.mode == IG_ACCEPT) {
        ig_output.mode = IG_ACCEPT;
        ig_state.mode = IG_ACCEPT;
        // count remains same
    } else if (ig_state.mode == IG_REJECT) {
        ig_output.mode = IG_REJECT;
        ig_state.mode = IG_REJECT;
        ig_output.consecutive_reject++;
        ig_state.consecutive_reject++;
    } else {
        // State is FAULT
        ig_output.mode = IG_FAULT;
        ig_state.mode = IG_FAULT;
        // count retained
    }
} else {
    ig_output.mode = IG_REJECT;
    ig_output.consecutive_reject = ig_state.consecutive_reject + 1;
    ig_state.mode = IG_REJECT;
    ig_state.consecutive_reject = ig_output.consecutive_reject;
}

if (ig_state.consecutive_reject >= ig_config.max_consecutive_reject) {
    ig_output.mode = IG_FAULT;
    ig_state.mode = IG_FAULT;
    // count is already incremented in the Reject branch or preserved, 
    // just ensure mode is fault.
}

ig_output.use_measurement = (ig_output.mode == IG_ACCEPT) ? 1 : 0;

